from pathlib import Path
import json
ROOT=Path(__file__).parent
apps=json.loads((ROOT/'apps.json').read_text())
backends=[
('iam-policy-engine','Identity Policy Auditor','Security','🐍','Audit RBAC decisions, account deactivation and separation-of-duties conflicts.','Python','Python • pytest'),
('rag-knowledge-search','Citation-Grounded RAG','AI / LLM','📚','Offline TF-IDF knowledge retrieval with citations, abstention and an optional OpenAI-compatible LLM.','Python','Python • NLP • LLM API'),
('incident-classifier','Incident Classifier','Machine Learning','🧠','TF-IDF and logistic regression pipeline for synthetic IT incident categorization.','Python','Python • scikit-learn'),
('ml-benchmark','ML Benchmark Suite','Machine Learning','📈','Reproducible Iris classification comparison with stratified cross-validation and test metrics.','Python','Python • scikit-learn'),
('log-anomaly-monitor','Log Anomaly Radar','Security','📡','Robust median-absolute-deviation spike detection with timestamped incident output.','Python','Python • Statistics'),
('api-uptime-monitor','API Uptime Watch','Backend','⏱️','Asynchronous HTTP health checks, strict timeouts and useful diagnostics.','Python','Python • Async • HTTPX'),
('file-integrity-cli','Integrity Manifest CLI','Security','📦','SHA-256 manifest creation and safe verification with path traversal protection.','Python','Python • CLI • Hashing'),
('bank-ledger','Bank Ledger Engine','Java / OOP','🏦','BigDecimal balances, synchronized atomic transfers, overdraft guards and audit events.','Java','Java 17 • OOP'),
('route-planner','Dijkstra Route Planner','Java / OOP','🗺️','Find shortest paths with adjacency lists and a min-priority queue.','Java','Java 17 • Algorithms'),
('lru-cache','LRU Cache System','Java / OOP','💾','Generic fixed-capacity LRU cache using access-ordered LinkedHashMap.','Java','Java 17 • Data Structures'),
('password-validator','Password Policy Validator','Java / OOP','🔐','Reusable password rules and explainable feedback without logging secrets.','Java','Java 17 • Security'),
('retail-analytics','Retail Analytics SQL','Database','🗄️','SQLite relational schema, normalized tables, window functions and revenue reporting.','SQL','SQLite • SQL • Python')]
for slug,title,cat,icon,desc,lang,tech in backends:
    path=f"{'sql' if lang=='SQL' else lang.lower()}/{slug}/"
    apps.append(dict(id=slug,title=title,category=cat,icon=icon,desc=desc,language=lang,tech=tech,level='Intermediate',url='https://github.com/sharanyapal/sharanya-pal-portfolio/tree/main/labs/'+path,live=False))
assert len(apps)==24
(ROOT/'projects.json').write_text(json.dumps(apps,indent=2,ensure_ascii=False))
for a in apps[:12]:
    (ROOT/'apps'/a['id']/'README.md').write_text('# '+a['title']+'\n\n'+a['desc']+'\n\n## Run\n\nOpen `index.html` in a local HTTP server or select **Launch demo** from the live gallery. No build or API key required.\n\n## Stack\n\n'+a['tech']+'\n\nAll calculations are local to the browser.\n',encoding='utf8')
for a in apps[12:]:
    p=ROOT / ('sql' if a['language']=='SQL' else a['language'].lower())/a['id']
    command='python main.py' if a['language']=='Python' else ('javac Main.java && java Main' if a['language']=='Java' else 'python demo.py')
    extra='\n\nDependencies: `pip install -r requirements.txt`\n' if (p/'requirements.txt').exists() else '\n\nNo third-party dependencies are required.\n'
    if a['language']=='SQL':command='python demo.py'
    (p/'README.md').write_text('# '+a['title']+'\n\n'+a['desc']+'\n\n## Run\n\n```bash\n'+command+'\n```\n'+extra+'\n## Notes\n\nDemonstration code uses local, synthetic, or publicly available sample data. No proprietary banking/client data.\n',encoding='utf8')
